arguments.cmd:
mkdir -p /app/output /app/work/pptx && cat > /app/work/pptx/generate_deck.js <<'EOF'
const pptxgen = require('pptxgenjs');
const fs = require('fs');
const path = require('path');

const pptx = new pptxgen();
pptx.layout = 'LAYOUT_16X9';
pptx.author = 'OpenAI';
pptx.company = 'OpenAI';
pptx.subject = 'Global CO2 emissions trends, regional shifts, and per capita inequalities';
pptx.title = 'Global CO₂ Emissions: Trends, Regional Shifts, and Per Capita Inequalities';
pptx.lang = 'en-US';
pptx.theme = {
  headFontFace: 'Aptos Display',
  bodyFontFace: 'Aptos',
  lang: 'en-US'
};
pptx.defineLayout({ name: 'CUSTOM_WIDE', width: 10, height: 5.625 });
pptx.layout = 'CUSTOM_WIDE';
pptx.margin = 0;
pptx.defineSlideMaster({
  title: 'MASTER',
  background: { color: 'F7FAFC' },
  objects: []
});
pptx.layout = 'CUSTOM_WIDE';
pptx.slideWidth = 10;
pptx.slideHeight = 5.625;
pptx.version = '1.0';
pptx.layout = 'LAYOUT_WIDE';

const out = '/app/output/final_deck.pptx';
const assets = '/app/benchmark/assets';
const has = (name) => fs.existsSync(path.join(assets, name));

const C = {
  navy: '102A43',
  blue: '1D4E89',
  teal: '2A9D8F',
  gold: 'E9C46A',
  orange: 'F4A261',
  red: 'E76F51',
  ink: '1F2937',
  muted: '64748B',
  light: 'F1F5F9',
  bg: 'F8FAFC',
  white: 'FFFFFF',
  green: '4B8B3B',
  purple: '6D597A',
  gray: 'CBD5E1'
};

const W = 13.333;
const H = 7.5;

function addBg(slide, color = C.bg) {
  slide.background = { color };
  slide.addShape(pptx.ShapeType.rect, { x: 0, y: 0, w: W, h: H, fill: { color }, line: { color } });
}

function addHeader(slide, title, kicker, page) {
  slide.addText(kicker || 'GLOBAL CO₂ EMISSIONS | 1750–2024', {
    x: 0.5, y: 0.27, w: 7.8, h: 0.22,
    fontFace: 'Aptos', fontSize: 8.5, bold: true, color: C.teal,
    charSpace: 1.2, margin: 0
  });
  slide.addText(title, {
    x: 0.5, y: 0.58, w: 10.1, h: 0.48,
    fontFace: 'Aptos Display', fontSize: 22, bold: true, color: C.navy,
    margin: 0, breakLine: false, fit: 'shrink'
  });
  slide.addShape(pptx.ShapeType.line, { x: 0.5, y: 1.18, w: 12.2, h: 0, line: { color: 'D7DEE8', width: 1 } });
  addPage(slide, page);
}

function addPage(slide, page) {
  slide.addShape(pptx.ShapeType.roundRect, {
    x: 12.22, y: 6.92, w: 0.58, h: 0.28,
    rectRadius: 0.04,
    fill: { color: C.navy, transparency: 5 }, line: { color: C.navy, transparency: 100 }
  });
  slide.addText(String(page).padStart(2, '0'), {
    x: 12.22, y: 6.965, w: 0.58, h: 0.15,
    fontSize: 7.5, bold: true, color: C.white, align: 'center', margin: 0
  });
}

function txt(slide, text, opt) {
  slide.addText(text, Object.assign({
    fontFace: 'Aptos', fontSize: 12, color: C.ink,
    margin: 0.04, breakLine: false, fit: 'shrink'
  }, opt));
}

function pill(slide, text, x, y, w, color, textColor = C.white) {
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h: 0.34, rectRadius: 0.08, fill: { color }, line: { color, transparency: 100 } });
  txt(slide, text, { x, y: y + 0.075, w, h: 0.15, align: 'center', fontSize: 8.2, bold: true, color: textColor });
}

function statCard(slide, value, label, x, y, w, h, color = C.blue, note) {
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h, rectRadius: 0.06, fill: { color: C.white }, line: { color: 'D9E2EC', width: 1 } });
  slide.addShape(pptx.ShapeType.rect, { x, y, w: 0.09, h, fill: { color }, line: { color, transparency: 100 } });
  txt(slide, value, { x: x + 0.22, y: y + 0.18, w: w - 0.35, h: 0.44, fontSize: 26, bold: true, color });
  txt(slide, label, { x: x + 0.24, y: y + 0.78, w: w - 0.38, h: 0.48, fontSize: 10.5, color: C.ink, bold: true, fit: 'shrink' });
  if (note) txt(slide, note, { x: x + 0.24, y: y + 1.28, w: w - 0.38, h: 0.35, fontSize: 8.5, color: C.muted, fit: 'shrink' });
}

function foot(slide, text) {
  txt(slide, text, { x: 0.5, y: 7.04, w: 10.7, h: 0.22, fontSize: 7.5, color: C.muted });
}

function imageBox(slide, file, x, y, w, h, label) {
  const p = path.join(assets, file);
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h, rectRadius: 0.04, fill: { color: C.white }, line: { color: 'D7DEE8', width: 1 } });
  if (fs.existsSync(p)) {
    slide.addImage({ path: p, x: x + 0.08, y: y + 0.08, w: w - 0.16, h: h - 0.4, sizingCrop: true });
  } else {
    txt(slide, 'Figure asset not provided', { x, y: y + h / 2 - 0.1, w, h: 0.25, align: 'center', fontSize: 11, color: C.muted, italic: true });
  }
  txt(slide, label, { x: x + 0.12, y: y + h - 0.25, w: w - 0.24, h: 0.15, fontSize: 7.4, color: C.muted, align: 'center' });
}

function drawLineChart(slide, x, y, w, h) {
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h, rectRadius: 0.04, fill: { color: C.white }, line: { color: 'D7DEE8', width: 1 } });
  const px = x + 0.45, py = y + 0.35, cw = w - 0.8, ch = h - 0.86;
  slide.addShape(pptx.ShapeType.line, { x: px, y: py + ch, w: cw, h: 0, line: { color: '9AA6B2', width: 1 } });
  slide.addShape(pptx.ShapeType.line, { x: px, y: py, w: 0, h: ch, line: { color: '9AA6B2', width: 1 } });
  [0, 10, 20, 30, 40].forEach(v => {
    const yy = py + ch - (v / 40) * ch;
    slide.addShape(pptx.ShapeType.line, { x: px, y: yy, w: cw, h: 0, line: { color: 'E5E7EB', width: 0.5, transparency: v === 0 ? 100 : 0 } });
    txt(slide, String(v), { x: x + 0.12, y: yy - 0.07, w: 0.25, h: 0.12, fontSize: 6.5, color: C.muted, align: 'right' });
  });
  const data = [
    { year: 1750, value: 0.05 }, { year: 1900, value: 2.0 }, { year: 1950, value: 6 },
    { year: 1990, value: 20.5 }, { year: 2024, value: 35.5 }
  ];
  const xmin = 1750, xmax = 2024, ymax = 40;
  const pts = data.map(d => ({ x: px + ((d.year - xmin) / (xmax - xmin)) * cw, y: py + ch - (d.value / ymax) * ch }));
  for (let i = 0; i < pts.length - 1; i++) {
    slide.addShape(pptx.ShapeType.line, { x: pts[i].x, y: pts[i].y, w: pts[i+1].x - pts[i].x, h: pts[i+1].y - pts[i].y, line: { color: C.red, width: 3 } });
  }
  pts.forEach((p, i) => slide.addShape(pptx.ShapeType.ellipse, { x: p.x - 0.055, y: p.y - 0.055, w: 0.11, h: 0.11, fill: { color: [C.teal, C.blue, C.gold, C.orange, C.red][i] }, line: { color: C.white, width: 1 } }));
  [{year:1950, label:'1950\n~6 Bt'}, {year:1990, label:'1990\n>20 Bt'}, {year:2024, label:'Today\n35+ Bt'}].forEach((d, idx) => {
    const p = pts.find(pp => Math.abs(pp.x - (px + ((d.year-xmin)/(xmax-xmin))*cw)) < 0.01) || {x:px,y:py};
    txt(slide, d.label, { x: p.x - (idx===2?0.5:0.35), y: p.y - 0.55, w: idx===2?0.85:0.65, h: 0.32, fontSize: 7.5, bold: true, color: C.navy, align: 'center' });
  });
  [1750, 1900, 1950, 1990, 2024].forEach(yr => {
    const xx = px + ((yr - xmin) / (xmax - xmin)) * cw;
    txt(slide, String(yr), { x: xx - 0.25, y: py + ch + 0.09, w: 0.5, h: 0.12, fontSize: 6.5, color: C.muted, align: 'center' });
  });
  txt(slide, 'Annual fossil fuel & industry CO₂ (billion tonnes)', { x: px, y: y + h - 0.22, w: cw, h: 0.13, fontSize: 6.8, color: C.muted, align: 'center' });
}

function hbar(slide, data, x, y, w, h, max, colorFn) {
  const rowH = h / data.length;
  data.forEach((d, i) => {
    const yy = y + i * rowH;
    txt(slide, d.name, { x, y: yy + 0.06, w: 1.25, h: 0.18, fontSize: 8.5, bold: d.bold, color: C.ink, align: 'right' });
    slide.addShape(pptx.ShapeType.roundRect, { x: x + 1.38, y: yy + 0.08, w: w - 2.1, h: 0.18, rectRadius: 0.03, fill: { color: 'E6EDF5' }, line: { color: 'E6EDF5', transparency: 100 } });
    const bw = (w - 2.1) * d.value / max;
    slide.addShape(pptx.ShapeType.roundRect, { x: x + 1.38, y: yy + 0.08, w: Math.max(bw, 0.035), h: 0.18, rectRadius: 0.03, fill: { color: colorFn ? colorFn(d, i) : C.blue }, line: { color: colorFn ? colorFn(d, i) : C.blue, transparency: 100 } });
    txt(slide, d.label, { x: x + w - 0.62, y: yy + 0.055, w: 0.55, h: 0.18, fontSize: 8.2, bold: true, color: C.navy, align: 'right' });
  });
}

function miniShare(slide, x, y) {
  const groups = [
    { label: 'Europe + US', v1900: 92, v2024: 31, c: C.blue },
    { label: 'Asia', v1900: 5, v2024: 50, c: C.red },
    { label: 'Africa', v1900: 1.5, v2024: 3.5, c: C.gold },
    { label: 'South America', v1900: 1.5, v2024: 3.5, c: C.teal },
  ];
  const barW = 1.35, barH = 3.45, gap = 1.1;
  [1900, 2024].forEach((year, col) => {
    let yy = y + barH;
    groups.forEach(g => {
      const val = year === 1900 ? g.v1900 : g.v2024;
      const hh = barH * val / 100;
      yy -= hh;
      slide.addShape(pptx.ShapeType.rect, { x: x + col * (barW + gap), y: yy, w: barW, h: hh, fill: { color: g.c }, line: { color: C.white, width: 0.5 } });
    });
    txt(slide, String(year), { x: x + col * (barW + gap), y: y + barH + 0.13, w: barW, h: 0.18, fontSize: 12, bold: true, align: 'center', color: C.navy });
  });
  txt(slide, '>90%', { x: x - 0.04, y: y + 0.18, w: barW + 0.08, h: 0.23, fontSize: 13, bold: true, align: 'center', color: C.white });
  txt(slide, '~50%', { x: x + barW + gap - 0.04, y: y + barH * 0.18, w: barW + 0.08, h: 0.23, fontSize: 13, bold: true, align: 'center', color: C.white });
  groups.forEach((g, i) => {
    const yy = y + 0.15 + i * 0.33;
    slide.addShape(pptx.ShapeType.rect, { x: x + 3.6, y: yy, w: 0.13, h: 0.13, fill: { color: g.c }, line: { color: g.c } });
    txt(slide, g.label, { x: x + 3.82, y: yy - 0.01, w: 1.7, h: 0.16, fontSize: 8.4, color: C.ink });
  });
}

function slide1() {
  const s = pptx.addSlide(); addBg(s, C.navy);
  s.addShape(pptx.ShapeType.rect, { x: 0, y: 0, w: W, h: H, fill: { color: C.navy }, line: { color: C.navy } });
  s.addShape(pptx.ShapeType.arc, { x: 8.7, y: -0.9, w: 4.8, h: 4.8, line: { color: C.teal, transparency: 45, width: 2 }, adjustPoint: 0.2 });
  s.addShape(pptx.ShapeType.arc, { x: 9.65, y: 0.1, w: 3.1, h: 3.1, line: { color: C.gold, transparency: 25, width: 1.4 }, adjustPoint: 0.25 });
  s.addText('GLOBAL CO₂ EMISSIONS', { x: 0.7, y: 0.72, w: 4.2, h: 0.22, fontSize: 10, bold: true, color: C.gold, charSpace: 1.5, margin: 0 });
  s.addText('Trends, Regional Shifts,\nand Per Capita Inequalities', { x: 0.7, y: 1.2, w: 8.5, h: 1.45, fontSize: 35, bold: true, color: C.white, breakLine: false, fit: 'shrink', margin: 0 });
  s.addShape(pptx.ShapeType.line, { x: 0.72, y: 2.9, w: 2.6, h: 0, line: { color: C.teal, width: 4 } });
  s.addText('Scope: 1750–2024 | Atmospheric milestone: Feb 2026', { x: 0.72, y: 3.25, w: 5.2, h: 0.28, fontSize: 15, color: 'DDEAF6', margin: 0 });
  statCard(s, '35+ Bt', 'annual fossil fuel & industry CO₂ today', 0.72, 4.14, 2.6, 1.35, C.red);
  statCard(s, '429 ppm', 'atmospheric CO₂ at Mauna Loa, Feb 2026', 3.55, 4.14, 2.85, 1.35, C.teal);
  s.addText('Sources: Global Carbon Budget 2025; NASA climate vital signs; NOAA Mauna Loa', { x: 0.72, y: 6.78, w: 8.2, h: 0.18, fontSize: 8.3, color: 'B9C7D5', margin: 0 });
  addPage(s, 1);
}

function slide2() {
  const s = pptx.addSlide(); addBg(s); addHeader(s, 'Atmospheric CO₂ Reaches 429 ppm — 50% Above Pre-Industrial Levels', 'ATMOSPHERIC MILESTONE', 2);
  statCard(s, '429 ppm', 'NOAA Mauna Loa measurement', 0.6, 1.55, 2.7, 1.55, C.teal, 'February 2026');
  statCard(s, '~280 ppm', 'pre-industrial baseline', 3.55, 1.55, 2.7, 1.55, C.blue, 'approximate level before large-scale fossil fuel use');
  statCard(s, '>50%', 'increase above baseline', 6.5, 1.55, 2.7, 1.55, C.red, 'more than 1.5× pre-industrial concentration');
  s.addShape(pptx.ShapeType.roundRect, { x: 0.7, y: 4.05, w: 11.8, h: 1.1, rectRadius: 0.06, fill: { color: C.white }, line: { color: 'D7DEE8' } });
  s.addShape(pptx.ShapeType.line, { x: 1.25, y: 4.6, w: 10.6, h: 0, line: { color: 'AAB7C4', width: 2 } });
  [
    { x: 1.35, label: 'Pre-industrial\n~280 ppm', c: C.blue },
    { x: 5.95, label: '1958\nMauna Loa record begins', c: C.gold },
    { x: 11.55, label: 'Feb 2026\n429 ppm', c: C.red },
  ].forEach(d => {
    s.addShape(pptx.ShapeType.ellipse, { x: d.x - 0.08, y: 4.52, w: 0.16, h: 0.16, fill: { color: d.c }, line: { color: C.white, width: 1 } });
    txt(s, d.label, { x: d.x - 0.75, y: 4.75, w: 1.5, h: 0.34, fontSize: 8.3, align: 'center', bold: true, color: C.ink });
  });
  txt(s, 'Ground-based and satellite measurements confirm sharp acceleration, linked primarily to burning coal, oil, and natural gas.', { x: 1.05, y: 5.75, w: 11.0, h: 0.34, fontSize: 15, bold: true, color: C.navy, align: 'center' });
  foot(s, 'Source: NASA climate vital signs; NOAA Mauna Loa Observatory.');
}

function slide3() {
  const s = pptx.addSlide(); addBg(s); addHeader(s, 'Global Fossil Fuel CO₂ Emissions Grew Six-Fold: 6 Billion to 35+ Billion Tonnes', 'GLOBAL TRAJECTORY', 3);
  drawLineChart(s, 0.72, 1.42, 7.15, 4.55);
  statCard(s, '~6 Bt', 'world emissions in 1950', 8.15, 1.48, 2.0, 1.05, C.gold);
  statCard(s, '>20 Bt', 'world emissions by 1990', 10.45, 1.48, 2.0, 1.05, C.orange);
  statCard(s, '35+ Bt', 'today: fossil fuels and industry', 9.0, 3.0, 2.6, 1.25, C.red);
  txt(s, 'Growth remained slow until the mid-20th century. Recent growth has slowed, but global emissions have not yet peaked.', { x: 8.35, y: 4.7, w: 3.85, h: 0.75, fontSize: 15, bold: true, color: C.navy, valign: 'mid' });
  pill(s, 'Figure reference: figure_2.jpg (trajectory)', 8.55, 5.74, 3.45, C.navy);
  foot(s, 'Source: Global Carbon Budget 2025. figure_2.jpg referenced in specification; source brief provides the values shown.');
}

function slide4() {
  const s = pptx.addSlide(); addBg(s); addHeader(s, 'China Now Emits Over 12 Billion Tonnes — More Than Double the United States', 'COUNTRY TOTALS', 4);
  const data = [
    { name: 'China', value: 12.5, label: '~12.5', c: C.red, bold: true },
    { name: 'United States', value: 5.0, label: '~5.0', c: C.blue, bold: true },
    { name: 'India', value: 3.0, label: '~3.0', c: C.orange },
    { name: 'EU-27', value: 2.7, label: '~2.7', c: C.teal },
    { name: 'Germany', value: 0.6, label: '~0.6', c: C.gray },
    { name: 'Brazil', value: 0.5, label: '~0.5', c: C.green },
    { name: 'UK', value: 0.3, label: '~0.3', c: C.purple },
    { name: 'France', value: 0.3, label: '~0.3', c: C.gold },
  ];
  hbar(s, data, 0.6, 1.48, 6.6, 3.6, 13, d => d.c);
  txt(s, 'Approx. annual CO₂ emissions, billion tonnes', { x: 2.0, y: 5.16, w: 4.0, h: 0.16, fontSize: 7.5, color: C.muted, align: 'center' });
  imageBox(s, 'figure_3.jpg', 7.58, 1.42, 4.95, 3.52, 'figure_3.jpg — Annual CO₂ emissions by country');
  statCard(s, '~27%', 'China share of global emissions', 7.75, 5.2, 1.85, 0.94, C.red);
  statCard(s, '~14%', 'United States share', 9.86, 5.2, 1.85, 0.94, C.blue);
  txt(s, 'China’s post-2000 rise contrasts with a US decline from its ~6 Bt peak around 2005.', { x: 0.72, y: 6.05, w: 6.4, h: 0.32, fontSize: 12.5, bold: true, color: C.navy });
  foot(s, 'Source: Global Carbon Budget 2025; Our World in Data.');
}

function slide5() {
  const s = pptx.addSlide(); addBg(s); addHeader(s, 'Asia Now Accounts for ~50% of Global Emissions; US + Europe Below One-Third', 'REGIONAL SHARE SHIFT', 5);
  s.addShape(pptx.ShapeType.roundRect, { x: 0.72, y: 1.43, w: 6.5, h: 4.65, rectRadius: 0.06, fill: { color: C.white }, line: { color: 'D7DEE8' } });
  miniShare(s, 1.18, 1.9);
  txt(s, 'Side-by-side stacked share visual: 1900 vs 2024', { x: 0.92, y: 5.55, w: 5.9, h: 0.18, fontSize: 8.3, color: C.muted, align: 'center' });
  statCard(s, '>90%', 'Europe + US share in 1900', 7.65, 1.55, 2.1, 1.05, C.blue);
  statCard(s, '>85%', 'Europe + US share in 1950', 10.05, 1.55, 2.1, 1.05, C.teal);
  statCard(s, '~50%', 'Asia share today', 7.65, 3.05, 2.1, 1.05, C.red);
  statCard(s, '3–4%', 'Africa and South America each', 10.05, 3.05, 2.1, 1.05, C.gold);
  txt(s, 'The geographic center of emissions has shifted from the early industrial economies to Asia — home to nearly 60% of the world’s population.', { x: 7.75, y: 4.82, w: 4.2, h: 0.65, fontSize: 14, bold: true, color: C.navy });
  foot(s, 'Source: Global Carbon Budget 2025. Shares are stated in the source brief.');
}

function slide6() {
  const s = pptx.addSlide(); addBg(s); addHeader(s, 'Per Capita Gap: 15 t in the US vs. 0.1 t in Chad — a 150× Disparity', 'PER CAPITA INEQUALITY', 6);
  const data = [
    { name: 'United States', value: 15, label: '~15 t', bold: true },
    { name: 'Canada', value: 13, label: '~13 t' },
    { name: 'China', value: 9, label: '~9 t' },
    { name: 'EU-27', value: 7, label: '~7 t' },
    { name: 'World average', value: 5, label: '~5 t', bold: true },
    { name: 'United Kingdom', value: 4, label: '~4 t' },
    { name: 'India', value: 2, label: '~2 t' },
    { name: 'Chad / Kenya', value: 0.1, label: '~0.1 / <1 t', bold: true },
  ];
  hbar(s, data, 0.75, 1.42, 7.45, 3.95, 15, (d, i) => i <= 1 ? C.red : i <= 3 ? C.orange : i === 4 ? C.navy : i === 7 ? C.teal : C.blue);
  s.addShape(pptx.ShapeType.line, { x: 3.13 + (6.03 * 5 / 15), y: 1.37, w: 0, h: 4.05, line: { color: C.navy, width: 1.2, dash: 'dash' } });
  txt(s, 'World average (~5 t)', { x: 4.82, y: 5.38, w: 1.4, h: 0.16, fontSize: 7.5, color: C.navy, bold: true, align: 'center' });
  imageBox(s, 'figure_1.jpg', 8.55, 1.45, 3.65, 2.45, 'figure_1.jpg — per capita line chart');
  statCard(s, '150×', 'gap between US / Australia and Chad / Niger', 8.76, 4.28, 2.95, 1.15, C.red, 'An average American or Australian emits in under two days what Chad or Niger emits in a year.');
  foot(s, 'Source: Global Carbon Budget 2025; Our World in Data. Per capita values are approximate tonnes per person per year.');
}

function slide7() {
  const s = pptx.addSlide(); addBg(s); addHeader(s, '2024 Snapshot: US and Europe Cut Emissions While Russia and SE Asia Increase', 'ANNUAL CHANGE MAP', 7);
  imageBox(s, 'figure_4.jpg', 0.72, 1.32, 7.25, 4.85, 'figure_4.jpg — Annual percentage change in CO₂ emissions, 2024');
  s.addShape(pptx.ShapeType.roundRect, { x: 8.35, y: 1.45, w: 3.8, h: 4.42, rectRadius: 0.06, fill: { color: C.white }, line: { color: 'D7DEE8' } });
  txt(s, 'Reading the 2024 map', { x: 8.62, y: 1.75, w: 3.2, h: 0.24, fontSize: 17, bold: true, color: C.navy });
  const bullets = [
    ['Blue', 'US and much of Europe: declines of roughly −1% to −5%.'],
    ['Orange/red', 'Russia, parts of Southeast Asia, and several African nations: +2% to +10% or more.'],
    ['South America', 'Mixed: one or two countries with very large >10% increases; others declined.']
  ];
  bullets.forEach((b, i) => {
    const y = 2.35 + i * 0.85;
    s.addShape(pptx.ShapeType.ellipse, { x: 8.62, y: y + 0.04, w: 0.15, h: 0.15, fill: { color: i === 0 ? C.blue : i === 1 ? C.red : C.teal }, line: { color: C.white } });
