      txt(s, r[i], { x: x + cols[i] + 0.12, y: yy + 0.33, w: cols[i+1] - cols[i] - 0.24, h: 0.65, fontSize: i === 0 ? 12 : 10, bold: i === 0 || i === 2, color: i === 0 ? C.navy : C.ink, align: i === 0 ? 'center' : 'left', fit: 'shrink' });
